return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Portuguese (Portugal)','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:33+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'pt_PT','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" guardado.','"%1$s" created. %2$d template updated.'=>'"%1$s" criado. %2$d modelo atualizado.' . "\0" . '"%1$s" criado. %2$d modelos atualizados.','"%s" created.'=>'"%s" criado.','%d language not yet linked'=>'%d idioma ainda não vinculado' . "\0" . '%d idiomas ainda não vinculados','%d link updated.'=>'%d link atualizado.' . "\0" . '%d links atualizados.','%d locale pack installed.'=>'%d pacote de idioma instalado.' . "\0" . '%d pacotes de idioma instalados.','%d navigation reference updated.'=>'%d referência de navegação atualizada.' . "\0" . '%d referências de navegação atualizadas.','%d part reference updated.'=>'%d referência de parte atualizada.' . "\0" . '%d referências de partes atualizadas.','%s Archive'=>'%s Arquivo','(avg %.1f hits/block)'=>'(média %.1f hits/bloco)','(avg %.1f hits/entry)'=>'(média %.1f hits/entrada)','(disabled)'=>'desativado','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} não tinha links substituíveis — re-escaneie para investigar)','.txt file(s) in the directory'=>'.txt ficheiro(s) no diretório','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d modelo(s) localizado(s) do tema &#8220;%2$s&#8221; estão preservados na base de dados, mas atualmente estão inativos. Eles tornar-se-ão ativos novamente se reativar esse tema. Para transferir as suas traduções para o novo tema, regenere-as através de <strong>Configurações → Lingua Forge → Roteador → Escaffold FSE</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> link(s) corrigível(eis) automaticamente','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> link(s) que precisam de revisão manual','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> caminho(s) obsoleto(s)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problema(s) de modelo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Aceita apenas arquivos .mo compilados. O nome do arquivo deve seguir o padrão {textdomain}-{locale}.mo. Carregar um arquivo com o mesmo nome de um existente substituirá o mesmo.','Action'=>'Ação','Actions'=>'Ações','active'=>'ativo','Active Languages'=>'Idiomas ativos','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Idiomas ativos: adicione cada idioma que deseja suportar. Cada idioma recebe um prefixo de URL ou subdomínio e uma tag hreflang na seção &lt;head&gt; da página.','Active Provider'=>'Provedor Ativo','Add entry'=>'Adicionar entrada','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Adicione instruções para melhorar o rascunho — por exemplo, torná-lo mais curto, adicionar uma seção de conclusão, usar um registro mais formal, incluir um bloco de FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Adicione instruções para melhorar o rascunho — por exemplo, torná-lo mais curto, adicionar uma seção de conclusão, usar um registo mais formal…','Add new entry'=>'Adicionar nova entrada','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Adicione um termo por linha. Tanto o termo de origem quanto a renderização alvo são obrigatórios. O par de línguas determina a quais trabalhos de tradução a restrição se aplica.','Adds a link to the home page so visitors can browse in their language.'=>'Adiciona um link para a página inicial para que os visitantes possam navegar no seu idioma.','Administrators only (manage_options)'=>'Apenas administradores (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Após alterar o idioma principal, limpe os permalinks (seção abaixo) para atualizar o roteamento de URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Após alterar as configurações de estrutura de URL (prefixo de caminho ↔ subdomínio), visite sempre Configurações → Ligações permanentes e clique em Guardar alterações para limpar as regras de reescrita.','AI Behaviour Preset'=>'Predefinição de Comportamento de IA','AI cache cleared. %d entry was removed.'=>'Cache de IA limpo. %d entrada foi removida.' . "\0" . 'Cache de IA limpo. %d entradas foram removidas.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Cache AI: lista respostas em cache do AI com contagens de acertos. Limpe toda a cache ou as entradas de uma única publicação. Use "Limpar" antes de testar uma alteração de tradução — resultados em cache são retornados mesmo quando você altera o preset ou o modelo do AI até que a entrada de cache seja removida.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Recursos de IA são opcionais. Roteamento de idioma, hreflang, o alternador de idiomas e o sistema de grupos de tradução funcionam sem um provedor configurado.','AI Limits & Security'=>'Limites e Segurança da IA','AI provider returned an empty response.'=>'O provedor de IA retornou uma resposta vazia.','AI Usage'=>'Uso de IA','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Objetivo de 120–160 caracteres. Deixe vazio para usar o fallback do excerto.','All time'=>'Todo o tempo','Allow editors to lock individual blocks'=>'Permitir que editores bloqueiem blocos individuais','Allow Gutenberg template-editing mode on post screens'=>'Permitir modo de edição de modelos do Gutenberg nas telas de postagem','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Também eliminar atribuições de idioma, relações de tradução, descrições meta, glossário e Memória de Tradução quando o plugin for desinstalado','Also generate meta description'=>'Também gerar descrição meta','Alternative (server-side):'=>'Alternativa (lado do servidor):','An unknown error occurred.'=>'Ocorreu um erro desconhecido.','and'=>'e','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'qualquer','API calls saved by cache'=>'Chamadas de API salvas pelo cache','API Key'=>'Chave API','API Keys'=>'Chaves API','API Keys Tab'=>'Aba de Chaves de API','API Response Cache'=>'Cache de Respostas de API','Applied ✓'=>'Aplicado ✓','Apply failed — please try again.'=>'Falha na aplicação — por favor, tente novamente.','Apply to Block'=>'Aplicar ao Bloco','Apply to Editor'=>'Aplicar ao Editor','Apply to Footnote'=>'Aplicar à Nota de Rodapé','Apply to Meta Description'=>'Aplicar à Meta Descrição','Apply translation'=>'Aplicar tradução','Applying…'=>'Aplicando…','Approximate size'=>'Tamanho aproximado','Archive'=>'Arquivo','Archive: %s'=>'Arquivo: %s','Authors and above (edit_published_posts)'=>'Autores e superiores (edit_published_posts)','Behavior'=>'Comportamento','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportamento: escolha o preset de IA (Literal, Balanceado, Criativo), adicione instruções personalizadas de prompt em todo o site, ative ou desative a tradução automática após salvar a publicação e configure a Memória de Tradução.','Block Content'=>'Conteúdo do bloco','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Exibe um aviso educado quando a página atual está sendo exibida no seu idioma de origem porque não existe tradução para o idioma do visitante. Impulsionado pelo sinal LINGUAFORGE_LANG_FALLBACK_ACTIVE do roteador Lingua Forge — não emite nada quando existe uma tradução para a localidade solicitada.','Block Editor'=>'Editor de Blocos','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'idioma','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'tradução','Block locking'=>'Bloqueio de blocos','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Padrões de blocos registrados para tipos de posts personalizados. Use o botão Traduzir para produzir uma variante de idioma. O conteúdo traduzido é salvo aqui e pode ser copiado para qualquer post CPT a partir do inseridor de padrões do editor de blocos ou usado como ponto de partida para um Padrão Sincronizado (Bloco Reutilizável).','block titleMissing Translation Notice'=>'Aviso de tradução ausente','Block translation reuses'=>'Reutilizações de tradução de blocos','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Cache de tradução de blocos ao nível do bloco compartilhado entre publicações. Quando ativado, blocos idênticos (mesmo markup, par de línguas e glossário) são servidos da memória em vez de chamar o AI novamente. Configure em Configurações → Comportamento.','Browser language redirect'=>'Redirecionamento de idioma do navegador','Built-in preset instructions:'=>'Instruções predefinidas incorporadas:','Bulletize (•-prefixed)'=>'Listar com marcadores (•-prefixado)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Armazena equivalentes traduzidos ao nível do bloco para que conteúdo reutilizável (rodapés compartilhados, barras laterais, acordeões, seções legais com muitas cláusulas) não pague uma chamada de API toda vez. Quando ativado, o fluxo de tradução analisa cada postagem em blocos, verifica cada bloco no cache e envia apenas blocos não armazenados em cache para a IA em uma única solicitação em lote. Edições de glossário e alterações na predefinição de conformidade invalidam automaticamente as traduções em cache afetadas. Veja estatísticas e limpe o cache em Manutenção.','cached'=>'em cache','Cached API responses'=>'Respostas de API em cache','Cached block translations'=>'Traduções de blocos em cache','Cancel'=>'Cancelar','Cannot determine target language from slug.'=>'Não foi possível determinar o idioma de destino a partir do slug.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limite o uso da IA que o site pode gerar e restrinja quais funções de usuário podem acionar chamadas pagas à IA. Sobrepõe-se ao limite de taxa por usuário (30 pedidos / minuto, codificado) que já protege contra loops descontrolados de um único usuário.','chars'=>'caracteres','Chunk translated'=>'Trecho traduzido','Chunk translated to:'=>'Trecho traduzido para:','Clear'=>'Limpar','Clear All'=>'Limpar tudo','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Limpar todos os resultados de IA em cache? Solicitações futuras irão acionar chamadas de API novas até que o cache seja reconstruído.','Clear API Response Cache'=>'Limpar Cache de Respostas de API','Clear Debug Files'=>'Limpar ficheiros de depuração','Clear hints'=>'Limpar dicas','Clear input'=>'Limpar entrada','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Limpar toda a Memória de Tradução? As traduções futuras reconstruirão o cache à medida que forem feitas.','Clear Translation Memory'=>'Limpar Memória de Tradução','Close'=>'Fechar','Close language panel'=>'Fechar painel de idiomas','Close popover'=>'Fechar popover','Compliance Preset'=>'Predefinição de conformidade','Content generated'=>'Conteúdo gerado','Content Generator'=>'Gerador de Conteúdo','Content ready'=>'Conteúdo pronto','Contributors and above — default (edit_posts)'=>'Colaboradores e superiores — padrão (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controle quanto conteúdo é enviado para a IA e quão grande pode ser a resposta. Deixe um campo em branco para usar o padrão interno (mostrado como espaço reservado). Aumente esses valores se páginas grandes estiverem sendo cortadas; reduza-os para diminuir custos de API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla o orçamento de tokens e limites de entrada para o recurso Gerador de Conteúdo de IA. Deixe os campos em branco para usar os padrões integrados.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla o que acontece quando um administrador remove o plugin de Plugins → Plugins instalados → Eliminar. As configurações do plugin e os caches de IA são sempre removidos. As atribuições de idioma e relações de tradução são mantidas por padrão para que uma desinstalação acidental ou uma reinstalação possam continuar de onde pararam.','Conversational'=>'Conversacional','Copied ✓'=>'Copiado ✓','Copy'=>'Copiar','Copy markup'=>'Copiar marcação','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Copie o resultado e cole onde for necessário (por exemplo, diretamente no campo de nota de rodapé).','Copy to safe storage'=>'Copiar para armazenamento seguro','Could not add entry: source term and target term are required.'=>'Não foi possível adicionar a entrada: termo de origem e termo de destino são obrigatórios.','Could not copy the file. Check that the uploads folder is writable.'=>'Não foi possível copiar o arquivo. Verifique se a pasta de uploads é gravável.','Could not instantiate the provider.'=>'Não foi possível instanciar o provedor.','Could not save the file. Check that the uploads folder is writable.'=>'Não foi possível salvar o arquivo. Verifique se a pasta de uploads é gravável.','Could not save the glossary entry.'=>'Não foi possível guardar a entrada do glossário.','CPT Block Patterns'=>'Padrões de blocos CPT','Create'=>'Criar','Create missing'=>'Criar ausentes','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Criar traduções para o tipo de publicação "%s" requer uma integração ativa. Por favor, assegure-se de que a integração necessária está instalada e ativa.','Creating…'=>'A criar…','Creative / Marketing'=>'Criativo / Marketing','Creative / Marketing instructions'=>'Instruções criativas / de marketing','Current content (will be overwritten)'=>'Conteúdo atual (será sobrescrito)','Current title'=>'Título atual','Current: {current}'=>'Atual: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Atualmente herdado da constante %s. Selecionar um valor aqui irá sobrescrevê-lo.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Atualmente ignorado para postagens que usam atributos de espaço reservado de comentário de bloco (campos de resumo wp:details, etc.) — eles passam para o caminho de tradução de chamada única existente.','Currently:'=>'Atualmente:','Custom'=>'Personalizado','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Quota diária de IA atingida (%1$d solicitações). Reinicia às %2$s UTC.','Daily request limit'=>'Limite diário de pedidos','Debug Files'=>'Arquivos de depuração','Debug files cleared. %d file was removed.'=>'Arquivos de depuração limpos. %d ficheiro foi removido.' . "\0" . 'Arquivos de depuração limpos. %d ficheiros foram removidos.','Debug logging'=>'Registo de depuração','Debug logging disabled.'=>'Registo de depuração desativado.','Debug logging enabled.'=>'Registo de depuração ativado.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Depuração: ative o log de depuração para capturar prompts de IA e respostas de API em um arquivo local. Desative após a resolução de problemas — o modo de depuração escreve um arquivo a cada solicitação de IA.','Delete'=>'Excluir','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Eliminar todos os ficheiros .txt no diretório de depuração? O próprio diretório permanecerá para que futuras gravações de depuração continuem a ser feitas de forma limpa.','Delete all files for this override (both .mo and .po)?'=>'Excluir todos os arquivos desta substituição (tanto .mo quanto .po)?','Delete content data on uninstall'=>'Eliminar dados de conteúdo na desinstalação','Delete this glossary entry?'=>'Deseja excluir esta entrada do glossário?','Describe what to write — topic, key points, structure…'=>'Descreva o que escrever — tópico, pontos-chave, estrutura…','Directory'=>'Diretório','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Desative durante ajuste de prompt ou quando precisar que cada solicitação alcance o provedor de IA. Desativar não exclui entradas em cache — reativar as restaura. Aumentar o gasto com API imediatamente em sites ocupados é esperado quando desativado.','Display'=>'Exibir','Displays the Lingua Forge language switcher.'=>'Exibe o seletor de idioma do Lingua Forge.','Documentation'=>'Documentação','Done'=>'Concluído','Done — {done} of {total} post(s) fixed.'=>'Concluído — {done} de {total} post(s) corrigido(s).','Down'=>'Para baixo','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Baixe e instale um pacote de idioma do núcleo do WordPress diretamente do WordPress.org. Uma vez instalado, o idioma fica disponível para roteamento de URL e fluxo de trabalho de tradução AI. A lista de idiomas disponíveis é buscada sob demanda — clique no botão abaixo para carregá-la.','Dropdown direction'=>'Direção do menu suspenso','Editors and above (edit_others_posts)'=>'Editores e superiores (edit_others_posts)','Enable API response caching'=>'Ativar cache de respostas de API','Enable block-level translation cache reuse across posts'=>'Permitir reutilização do cache de tradução ao nível do bloco entre postagens','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Insira sua chave de API para pelo menos um provedor de IA. As chaves são criptografadas em repouso usando AES-256-GCM com um segredo específico do site (LINGUAFORGE_SECRET). Não compartilhe exportações de banco de dados sem rotacionar o segredo primeiro.','environment variable'=>'variável de ambiente','Error'=>'Erro','Expand'=>'Expandir','Expected: {expected}'=>'Esperado: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Orientação extra — tom, estilo, restrições, público-alvo…','Extra guidance — tone, style, constraints…'=>'Orientação extra — tom, estilo, restrições…','Failed. Please try again.'=>'Falhou. Por favor, tente novamente.','Feature'=>'Funcionalidade','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Os recursos são agrupados em dois níveis. Insira o identificador exato do modelo para cada nível e provedor. Deixe um campo em branco para usar o padrão embutido (mostrado como espaço reservado). Apenas os modelos do provedor ativo são chamados em tempo de execução — configure os outros com antecedência se planeja trocar.','File copied to safe storage successfully.'=>'Arquivo copiado para armazenamento seguro com sucesso.','Files'=>'Arquivos','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Os ficheiros são guardados no diretório abaixo. Útil para diagnosticar problemas de tradução — desative assim que tiver o que precisa para evitar o acúmulo de ficheiros. Também pode forçar isto a partir do wp-config.php com `define( \'LINGUAFORGE_AI_DEBUG\', true );` que substitui o botão.','Filter'=>'Filtro','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtre com linguaforge_debug_dir para redirecionar a saída de depuração para um local não público.','Fix'=>'Corrigir','Fix All'=>'Corrigir tudo','Fix all links'=>'Corrigir todos os links','Fix all parts'=>'Corrigir todas as partes','Fix Links'=>'Corrigir links','Fix Nav'=>'Corrigir navegação','Fix Parts'=>'Corrigir partes','Fix Template'=>'Corrigir Modelo','Fixing {n} / {total}…'=>'Corrigindo {n} / {total}…','Fixing…'=>'A corrigir…','Flush Permalink Rules'=>'Limpar regras de permalink','Flush Permalinks'=>'Limpar Permalinks','Footnote Content'=>'Conteúdo da nota de rodapé','footnote(s) translated — applied together with content.'=>'Notas de rodapé traduzidas — aplicadas juntamente com o conteúdo.','Footnotes'=>'Notas de rodapé','Footnotes payload (advanced)'=>'Carga útil de notas de rodapé (avançado)','Forbidden'=>'Proibido','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçado DESATIVADO pela constante LINGUAFORGE_AI_DEBUG no wp-config.php. Remova essa linha para controlar este botão a partir daqui.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçado ATIVADO pela constante LINGUAFORGE_AI_DEBUG no wp-config.php. Remova essa linha para controlar este botão a partir daqui.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Encontrado(s) {parts} em <strong>{total}</strong> de <strong>{scanned}</strong> post(s) escaneado(s) para <strong>{lang}</strong>.','From'=>'De','Front Page'=>'Página inicial','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localização FSE: esqueleto, tradução e correção de links em modelos e partes de modelos de Edição Completa do Site diretamente nesta aba.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Modelos FSE semeados a partir do tema ativo. Crie e personalize no Editor do Site.','Full Article'=>'Artigo completo','Full post'=>'Post completo','General'=>'Geral','Generate'=>'Gerar','Generate Content'=>'Gerar conteúdo','Generate content…'=>'Gerar conteúdo…','Generate Excerpt'=>'Gerar excerto','Generate Meta Description'=>'Gerar descrição meta','Generated Content'=>'Conteúdo gerado','Generated meta description'=>'Meta descrição gerada','Generating…'=>'A gerar…','Generation failed.'=>'Falha na geração.','Getting started'=>'Começando','Global AI preset'=>'Predefinição global de IA','Global default (%s)'=>'Padrão global (%s)','Glossary'=>'Glossário','Glossary entry added.'=>'Entrada do glossário adicionada.','Glossary entry removed.'=>'Entrada do glossário removida.','Glossary Tab'=>'Aba de Glossário','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Ocultar','Hints'=>'Dicas','Home link text'=>'Texto do link para a página inicial','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Como deve aparecer na tradução. Digite o mesmo valor do termo de origem para instruir a IA a preservá-lo exatamente.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ícone + etiqueta','Icon only'=>'Apenas ícone','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Se marcado, ao desinstalar o plugin, todos as atribuições de idioma, relações de tradução, descrições meta, predefinições de página, o glossário de IA e a Memória de Tradução serão apagados permanentemente de todos os posts neste site. Isto não pode ser desfeito. Deixe desmarcado a menos que esteja a remover totalmente o suporte multilíngue do site.','Improve writing'=>'Melhorar escrita','Informative'=>'Informativo','Input tokens'=>'Tokens de entrada','Install'=>'Instalar','Install a Language'=>'Instalar um idioma','Installing…'=>'A instalar…','Instructions (optional)'=>'Instruções (opcional)','Instructions / key points'=>'Instruções / pontos-chave','Integration API'=>'API de Integração','Internal Link Fixer'=>'Corretor de links internos','Introduction only'=>'Apenas introdução','Invalid file reference.'=>'Referência de arquivo inválida.','Invalid filename.'=>'Nome de arquivo inválido.','Invalid language.'=>'Idioma inválido.','Invalid locale code.'=>'Código de idioma inválido.','Invalid or primary language.'=>'Idioma inválido ou principal.','Invalid post type.'=>'Tipo de publicação inválido.','Invalid template part.'=>'Parte do modelo inválida.','Invalid template type.'=>'Tipo de modelo inválido.','Key points, ideas, or structure to build from…'=>'Pontos-chave, ideias ou estrutura a partir da qual construir…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'As chaves são criptografadas com AES-256-CBC antes de serem armazenadas na base de dados do WordPress. O segredo de criptografia é derivado dos seus salts de autenticação do WordPress (wp-config.php), portanto, chaves em texto simples nunca entram na base de dados.','Language'=>'Idioma','Language %s installed successfully.'=>'Idioma %s instalado com sucesso.','Language (optional)'=>'Idioma (opcional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'A instalação de idiomas está desativada neste servidor (DISALLOW_FILE_MODS está definido).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'A instalação de idiomas está desativada neste servidor. A constante DISALLOW_FILE_MODS está definida no wp-config.php. Instale pacotes de idioma manualmente via WP-CLI: wp language core install de_DE','Language label'=>'Etiqueta de idioma','Language Overrides'=>'Substituições de idioma','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Sobrescritas de idioma: gerencie arquivos de sobrescrita personalizados .po/.mo para as strings da interface do Lingua Forge. Use isto em vez de editar arquivos do plugin diretamente — as sobrescritas sobrevivem às atualizações.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Falha na instalação do pacote de idioma. O idioma pode já estar instalado, o código de idioma pode estar incorreto ou seu servidor pode bloquear gravações de arquivos.','Language Setup'=>'Configuração de idioma','Language Switcher'=>'Seletor de idioma','Language switcher'=>'Alternador de idiomas','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Cópias específicas de idioma das partes do modelo do tema. Uma vez estruturados, os modelos são atualizados para referenciar a parte específica do idioma.','Language:'=>'Idioma:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Idiomas atualmente conhecidos pelo roteador (derivados dos pacotes de idioma do WordPress instalados mais o idioma principal). Instale pacotes de idioma adicionais na seção abaixo para disponibilizar mais idiomas para roteamento e tradução.','Last 30 days'=>'Últimos 30 dias','Last 7 days'=>'Últimos 7 dias','Lead paragraph (≤60 w)'=>'Parágrafo introdutório (≤60 palavras)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Deixe um campo de modelo em branco para usar o padrão incorporado para esse nível. O texto do espaço reservado mostra qual modelo será usado.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deixe em branco para nomes de marcas e termos independentes de idioma que devem ser preservados independentemente do idioma de origem.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deixe em branco para aplicar esta entrada a todos os idiomas de destino — ideal para nomes de marcas, abreviaturas e termos que devem ser preservados exatamente em todas as traduções.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deixe em branco para manter a chave existente. Insira um novo valor para substituí-la.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deixe em branco para usar o padrão embutido. Limpar uma substituição salva restaura o padrão na próxima gravação.','Legal / Compliance'=>'Legal / Conformidade','Legal / Compliance instructions'=>'Instruções legais / de conformidade','Light'=>'Leve','Light (default — fast and cost-effective)'=>'Leve (padrão — rápido e econômico)','Light (fast and cost-effective — Haiku / Flash)'=>'Leve (rápido e econômico — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Leve: usado para descrições meta e geração de excertos — rápido, de baixo custo.','Limit results to pages in the given Lingua Forge language code.'=>'Limitar resultados às páginas no código de idioma do Lingua Forge fornecido.','Limits'=>'Limites','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge adiciona roteamento multilíngue, tradução alimentada por IA, tags hreflang de SEO e um alternador de idiomas ao seu site WordPress.','Lingua Forge AI Tools'=>'Ferramentas de IA Lingua Forge','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'A Lingua Forge restringe por padrão dois recursos do Gutenberg para manter o comportamento editorial consistente entre idiomas. Opte aqui quando precisar de capacidades completas do Gutenberg / FSE.','Lingua Forge Settings'=>'Configurações do Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge usa duas camadas de cache independentes para evitar chamadas redundantes à API de IA. Use as abas abaixo para inspecionar e gerenciar cada uma.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge usa dois níveis de modelos por provedor:','Lingua Forge — Quick Translate'=>'Lingua Forge — Tradução rápida','Lingua Forge — Settings'=>'Lingua Forge — Configurações','link(s)'=>'link(s)','Links'=>'Links','Load available languages'=>'Carregar idiomas disponíveis','Loading…'=>'A carregar…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'O Loco Translate armazena suas traduções personalizadas em wp-content/languages/loco/ — um local que pode ser apagado silenciosamente por uma atualização do núcleo do WP, reinstalação do plugin ou se o próprio Loco Translate for removido. Copiar arquivos aqui os move para o diretório Lingua Forge i18n-overrides, que persiste através de todos esses eventos e é carregado automaticamente em cada solicitação.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copiar para Armazenamento Seguro','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Menor capacidade do WordPress permitida para acionar recursos de IA. Restringir isso em sites com múltiplos autores impede que Colaboradores ou contas de teste executem chamadas pagas à IA. Pode sobrepor por recurso através do filtro linguaforge_required_capability.','Maintenance'=>'Manutenção','Maintenance Tab'=>'Aba de Manutenção','Make casual'=>'Tornar casual','Make concise'=>'Tornar conciso','Make formal'=>'Tornar formal','Mark citations needed'=>'Marcar citações necessárias','Max context characters'=>'Máximo de caracteres de contexto','Max hints characters'=>'Máximo de caracteres de dicas','Max input characters'=>'Máximo de caracteres de entrada','Max output tokens'=>'Máximo de tokens de saída','Maximum characters accepted from the input field. Default: 8 000.'=>'Número máximo de caracteres aceitos do campo de entrada. Padrão: 8 000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Número máximo de caracteres do conteúdo existente da publicação passado para a IA como contexto semente quando nenhuma Dica é fornecida. Padrão: 6 000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Número máximo de caracteres lidos do campo de Dicas. Padrão: 2 000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Número máximo de caracteres do conteúdo da publicação encaminhado para a IA. 0 significa sem limite — o conteúdo completo é sempre enviado (recomendado). Defina um valor diferente de zero apenas se o seu provedor tiver uma janela de contexto restrita. Um aviso é registrado no log de erros do PHP sempre que o conteúdo é cortado.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Número máximo de tokens que a IA pode produzir numa única resposta de tradução. Se uma tradução for cortada silenciosamente no final, aumente este valor. Padrão: 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Tokens máximos que a IA pode produzir por execução de geração. Aumente se artigos completos estiverem sendo cortados. Padrão: 8 192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Tokens máximos que a IA pode produzir por tradução rápida. Padrão: 2 000.','Meta Description'=>'Meta descrição','Meta Description, Excerpt Generator'=>'Descrição Meta, Gerador de Resumo','Minimum role'=>'Nível mínimo','Missing pattern name or language.'=>'Nome do padrão ou idioma ausente.','Mode'=>'Modo','Model'=>'Modelo','Model tier'=>'Nível do modelo','Models'=>'Modelos','Models Tab (General)'=>'Aba de Modelos (Geral)','Most recent cached block'=>'Bloco em cache mais recente','Most recent cached response'=>'Resposta em cache mais recente','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Roteamento multilíngue, meta tags de SEO e ferramentas de conteúdo AI para WordPress. Combina deteção de idioma, roteamento de URLs, hreflang, descrições meta e recursos de excerto, meta e tradução alimentados por IA.','Name displayed in this language. Leave empty to use the source name.'=>'Nome exibido neste idioma. Deixe vazio para usar o nome original.','Navigation'=>'Navegação','Navigation has no content to translate.'=>'Navegação não tem conteúdo para traduzir.','Navigation not found.'=>'Navegação não encontrada.','Navigation posts are translated via the Router tab, not this button.'=>'As publicações de navegação são traduzidas via a aba Router, não por este botão.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'A tradução de navegação requer um provedor de IA ativo. Configure uma chave de API na aba Chaves de API.','Navigations'=>'Navegações','Network error — could not reach the WordPress AJAX endpoint.'=>'Erro de rede — não foi possível alcançar o endpoint AJAX do WordPress.','No %s version found in this translation group.'=>'Nenhuma versão de %s encontrada neste grupo de tradução.','No AI provider configured.'=>'Nenhum provedor de IA configurado.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nenhum uso de IA registrado na janela selecionada (%s). Selecione um intervalo mais amplo acima.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Ainda não há uso de IA registrado. Assim que um editor executar uma tradução, gerar uma meta descrição ou usar qualquer outra funcionalidade de IA, os totais aparecerão aqui.','No API key configured for this provider.'=>'Nenhuma chave API configurada para este provedor.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Sem instruções predefinidas — cada recurso de IA usa os seus próprios padrões ajustados. Preencha o campo de instruções de prompt personalizado abaixo para adicionar as suas próprias regras para todo o site.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Ainda não foram encontrados arquivos personalizados do Loco Translate. Eles aparecem aqui assim que você salva uma tradução no Loco Translate.','No file was selected.'=>'Nenhum arquivo foi selecionado.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Nenhuma entrada do glossário corresponde ao filtro atual. Limpe o filtro para ver todas as entradas ou adicione uma nova entrada abaixo.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Ainda não há entradas no glossário. Adicione uma abaixo para começar a aplicar terminologia nas traduções.','No internal links found to update.'=>'Nenhum link interno encontrado para atualizar.','No language-specific template parts found to map.'=>'Nenhuma parte do modelo específica de idioma encontrada para mapear.','No navigation references needed updating.'=>'Nenhuma referência de navegação precisa ser atualizada.','No override files uploaded yet.'=>'Ainda não foram carregados arquivos de substituição.','No response from provider — check the error log for details.'=>'Sem resposta do fornecedor — verifique o registo de erros para detalhes.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Nenhum idioma secundário configurado. Instale um pacote de idioma acima para ativar a estrutura de modelos.','No source content found to translate.'=>'Não foi encontrado conteúdo fonte para traduzir.','No source page linked yet.'=>'Ainda não há página fonte vinculada.','No template part references needed updating.'=>'Nenhuma referência de parte do modelo precisa ser atualizada.','No {lang} translation registered (TRID missing)'=>'Nenhuma tradução em {lang} registrada (TRID ausente)','Notes'=>'Notas','Notice message'=>'Mensagem de aviso','Notice settings'=>'Configurações de aviso','Oldest cached block'=>'Bloco em cache mais antigo','Oldest cached response'=>'Resposta em cache mais antiga','Only .mo files are accepted.'=>'Apenas arquivos .mo são aceitos.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contexto opcional para editores (por exemplo, "ASIC = Circuito Integrado Específico de Aplicação; manter em inglês em contextos técnicos").','Output'=>'Saída','Output tokens'=>'Tokens de saída','overridden'=>'sobrescrito','Override file deleted.'=>'Arquivo de substituição excluído.','Override file uploaded successfully.'=>'Arquivo de substituição carregado com sucesso.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobrescreve a predefinição de IA para Tradução e Geração de Conteúdo nesta página. Todas as outras funcionalidades sempre usam a predefinição global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobrescreve a predefinição de IA para Tradução e Geração de Conteúdo nesta página. Instruções personalizadas de prompt em todo o site (Configurações → Comportamento) são sempre adicionadas a cada solicitação, independentemente desta seleção.','Overview'=>'Visão geral','Page'=>'Página','Part'=>'Parte','Paste a footnote, sentence, or any snippet here…'=>'Cole aqui uma nota de rodapé, frase ou qualquer trecho…','Paste text, or select text in the editor first…'=>'Cole o texto, ou selecione o texto no editor primeiro…','Paste text, or select text on the page first…'=>'Cole o texto, ou selecione o texto na página primeiro…','Paste your API key…'=>'Cole sua chave API…','Path prefix — example.com/de/'=>'Prefixo de caminho — exemplo.com/de/','Pattern'=>'Padrão','Pattern has no content to translate.'=>'O padrão não tem conteúdo para traduzir.','Pattern not found.'=>'Padrão não encontrado.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Padrão traduzido e salvo. Copie o conteúdo para o seu post CPT através do inseridor de padrões do editor de blocos ou use-o como ponto de partida para um Bloco Reutilizável.','Pattern translation failed.'=>'Falha na tradução do padrão.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Cache por publicação para traduções geradas por IA, descrições meta, excertos e conteúdo. Sempre ativo — sem necessidade de alternar. Entradas são invalidadas automaticamente quando o conteúdo ou o provedor/modelo de IA muda. Use o botão "↺ Re-traduzir" na barra de ferramentas ou clique em Limpar abaixo para forçar uma nova chamada à API.','Permalink rules flushed successfully.'=>'Regras de permalink limpas com sucesso.','Permission denied.'=>'Permissão negada.','Persuasive'=>'Persuasivo','PHP constant'=>'constante PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Fixe termos que não devem ser traduzidos ou que sempre devem ser renderizados de uma maneira específica (por exemplo, nomes de marcas, nomes de produtos, siglas). Restrições do glossário são injetadas em cada solicitação de tradução de IA para todos os recursos: tradução de publicação, descrição meta, excerto e tradução de modelos FSE.','Plain language'=>'Linguagem simples','Please enter some instructions first…'=>'Por favor, insira algumas instruções primeiro…','Please enter some text first…'=>'Por favor, insira algum texto primeiro…','Post'=>'Post','Post not found.'=>'Publicação não encontrada.','Post Types'=>'Tipos de Post','Prefilled from excerpt. Edit to override.'=>'Pré-preenchido a partir do excerto. Edite para substituir.','Primary Language'=>'Idioma principal','Primary language'=>'Idioma principal','Primary language saved.'=>'Idioma principal guardado.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Idioma principal: o idioma em que seu conteúdo existente está escrito. Todas as traduções são produzidas a partir deste idioma; alterá-lo não move nem exclui publicações.','Processing…'=>'A processar…','Provider'=>'Provedor','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'O provedor não retornou texto. Verifique o log de erros do WordPress para a razão detalhada da falha.','Quality'=>'Qualidade','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualidade (padrão — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualidade (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualidade: usada para tradução de publicações e geração de conteúdo — maior qualidade, maior custo.','Quick Translate'=>'Tradução rápida','Quick Translation'=>' Tradução rápida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'A Tradução rápida é usada para modo de fragmento/pedaço — passagens curtas traduzidas sob demanda a partir da barra de ferramentas, editor ou popovers de blocos. Usa uma configuração separada e mais leve do que a tradução de página inteira para manter as respostas rápidas e econômicas.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Reativa o canLockBlocks do Gutenberg. Útil para modelos editoriais que precisam impedir que colaboradores movam ou excluam blocos específicos.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Reativa supportsTemplateMode. Fundamental para fluxos de trabalho de Edição Completa do Site onde as substituições de modelos ao nível da postagem são intencionais.','Re-generates and updates the cached result.'=>'Regera e atualiza o resultado em cache.','Re-scan'=>'Reescanear','Re-scanning…'=>'Re-escaneando…','Re-translate'=>'Re-traduzir','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirecione os visitantes para o seu idioma preferido com base no cabeçalho Accept-Language do navegador','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Refinar mais — por exemplo, "tornar mais curto" ou "usar um tom formal"…','Refine further:'=>'Refinar mais:','Refinement'=>'Refinamento','Refinement failed — please try again.'=>'Falha na refinamento — por favor, tente novamente.','Refining…'=>'A Refinar…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera as regras de reescrita do WordPress para que os prefixos de URL, os slugs específicos de idioma e as reescritas de arquivo estejam sincronizados. Necessário após alterar o idioma principal ou adicionar suporte a novos idiomas.','Remove stored key'=>'Remover chave armazenada','Report an issue on GitHub'=>'Relatar um problema no GitHub','Request failed — please try again.'=>'Falha na solicitação — por favor, tente novamente.','Request failed.'=>'Falha na solicitação.','Request failed. Check your connection.'=>'Falha na solicitação. Verifique a sua conexão.','Request failed. Please try again.'=>'Falha na solicitação. Por favor, tente novamente.','Requests'=>'Solicitações','Reset'=>'Reiniciar','Result will appear here…'=>'O resultado aparecerá aqui…','Retranslate'=>'Retraduzir','Retranslating…'=>'Retraduzindo…','Review carefully — links and slugs not updated.'=>'Revise cuidadosamente — links e slugs não atualizados.','Review translation before applying'=>'Revisar tradução antes de aplicar','Revise'=>'Revisar','Revision'=>'Revisão','Revision Type'=>'Tipo de revisão','Router'=>'Roteador','Router Tab'=>'Aba de Roteador','Save Debug Setting'=>'Salvar configuração de depuração','Save Router Settings'=>'Salvar configurações do roteador','Save Settings'=>'Guardar configurações','Save the post to persist changes.'=>'Guarde a publicação para persistir as alterações.','Save Uninstall Setting'=>'Salvar configuração de desinstalação','Saved to the meta description field when you apply.'=>'Salvo no campo de meta descrição ao aplicar.','Scan failed: '=>'Falha na varredura: ','Scan request failed. Please try again.'=>'Falha na solicitação de varredura. Por favor, tente novamente.','Scanning posts for broken language links…'=>'Escaneando posts em busca de links de idioma quebrados…','Search'=>'Pesquisar','Search Results'=>'Resultados da pesquisa','Security check failed — file path is not permitted.'=>'Falha na verificação de segurança — caminho do arquivo não permitido.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecione um idioma para gerenciar seus modelos FSE, partes de modelos e menus de navegação.','Select language'=>'Selecionar idioma','SEO character-count info'=>'Informação de contagem de caracteres para SEO','Server setup (subdomain)'=>'Configuração do servidor (subdomínio)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Define o comportamento padrão de IA para todos os recursos em todo o site. Postagens individuais podem sobrescrever isso para Tradução e Geração de Conteúdo via a caixa meta Lingua Forge.','Settings'=>'Configurações','Settings saved.'=>'Configurações guardadas.','Show home link'=>'Mostrar link para a página inicial','Shown when no translation exists for the visitor\'s language.'=>'Mostrado quando não existe tradução para o idioma do visitante.','Single'=>'Único','Single %s'=>'Singular %s','Single: %s'=>'Singular: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Limite máximo de pedidos de IA por dia UTC (conta traduções na Toolbar e revisões de blocos). O contador reinicia à meia-noite UTC. Defina como 0 para desativar o limite.','Size'=>'Tamanho','Some link fixes failed.'=>'Algumas correções de links falharam.','Some nav ref fixes failed.'=>'Algumas correções de referências de navegação falharam.','Some part fixes failed.'=>'Algumas correções de partes falharam.','Some parts could not be created.'=>'Algumas partes não puderam ser criadas.','Some templates could not be created.'=>'Alguns modelos não puderam ser criados.','Some translations failed.'=>'Algumas traduções falharam.','Source file not found.'=>'Arquivo de origem não encontrado.','Source lang'=>'Idioma de origem','Source language'=>'Idioma de origem','Source term'=>'Termo de origem','Standard'=>'Padrão','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'O padrão usa a temperatura ajustada de cada recurso: Tradução T=0.2 (preciso), Tradução Rápida T=0.4, Gerador de Conteúdo T=0.6 (criativo). Os outros predefinições aplicam uma única temperatura fixa a todos os recursos.','Status'=>'Estado','Status / Actions'=>'Status / Ações','Storytelling'=>'Contar histórias','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modo de preservação rigorosa para conteúdo legal, regulatório, médico ou técnico. Quando ativado, cada recurso de IA usa uma temperatura de amostragem baixa e adiciona o adendo abaixo ao seu prompt do sistema — terminologia, números de artigos, unidades, nomes de marcas e linguagem regulatória são preservados exatamente, em vez de parafraseados.','Structured Outline'=>'Esboço estruturado','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'O modo de subdomínio requer que o seu servidor web aponte todos os subdomínios de idioma (por exemplo, de.exemplo.com) para esta instalação do WordPress. Após alterar os modos, limpe as regras de permalink e limpe quaisquer caches. Se a sua URL inicial incluir www (por exemplo, www.exemplo.com), use o filtro lf_base_domain para definir o domínio raiz sem o www, para que os subdomínios sejam construídos corretamente.','Subdomain — de.example.com/'=>'Subdomínio — de.exemplo.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Provedores suportados: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Apenas um provedor está ativo de cada vez. Selecione o provedor ativo na aba Geral.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, por recurso','Target lang'=>'Idioma de destino','Target Language'=>'Idioma de destino','Target language'=>'Idioma de destino','Target term'=>'Termo de destino','Target: 140–160 chars for optimal SERP display'=>'Alvo: 140–160 caracteres para exibição ideal na SERP','Technical'=>'Técnico','Technical / Scientific'=>'Técnico / Científico','Technical / Scientific instructions'=>'Instruções técnicas / científicas','Template "%s" already exists.'=>'Modelo "%s" já existe.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'O modelo "{expected}" não existe — crie-o primeiro no Editor do Site.','Template has no content.'=>'O modelo não tem conteúdo.','Template mode'=>'Modo de modelo','Template not found or not stored in the database.'=>'Modelo não encontrado ou não armazenado na base de dados.','Template part "%s" already exists.'=>'Parte do modelo "%s" já existe.','Template part has no content.'=>'A parte do modelo não tem conteúdo.','Template part not found or not stored in the database.'=>'Parte do modelo não encontrada ou não armazenada na base de dados.','Template Parts'=>'Partes do Modelo','Templates'=>'Modelos','Test connection'=>'Testar conexão','Testing…'=>'A testar…','Text domain / locale'=>'Domínio de texto / localidade','Text to translate'=>'Texto a traduzir','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'O Cache de Respostas de API armazena o resultado bruto de cada solicitação de IA — tradução, descrição meta, excerto e geração de conteúdo — indexado por um hash das entradas (conteúdo, par de línguas, provedor, modelo). Solicitações subsequentes com entradas idênticas são atendidas do cache sem chamada à API. O cache é diferente da Memória de Tradução: a Memória de Tradução opera ao nível do bloco e é compartilhada entre publicações; o Cache de Respostas de API opera ao nível do recurso e é indexado por publicação.','The editor did not accept the content — please try again.'=>'O editor não aceitou o conteúdo — por favor, tente novamente.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'O nível Leve usa o modelo rápido configurado na tabela de Modelos acima (padrão: Haiku / Flash). Mude para Qualidade se precisar da mesma precisão de tradução que o modo de página inteira para trechos.','The phrase as it appears in the source text.'=>'A frase como aparece no texto de origem.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'O idioma principal é sempre servido na raiz do seu site — sem prefixo de URL em modo de caminho, sem subdomínio de idioma em modo de subdomínio. Todos os outros idiomas usam um prefixo de caminho /lang/ (exemplo: exemplo.com/de/) ou um subdomínio de idioma (exemplo: de.exemplo.com), dependendo da configuração de estrutura de URL abaixo.','The source page has no footnotes.'=>'A página fonte não possui notas de rodapé.','The upload failed — please try again.'=>'Falha no upload — por favor, tente novamente.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Estas notas de rodapé vêm da página fonte e são exibidas aqui apenas para referência. Adicione-as a esta página usando o editor de blocos.','This is the source page. Footnotes are edited directly in the block editor.'=>'Esta é a página fonte. Notas de rodapé são editadas diretamente no editor de blocos.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Esta chave está atualmente fornecida por um servidor %s e não pode ser removida aqui. Insira uma nova chave acima para substituí-la por um valor do banco de dados.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Dica: para redefinir um modelo para o padrão embutido, limpe o campo e salve.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Para usar um segredo de criptografia personalizado (em vez do valor derivado wp_salt), adicione isto ao wp-config.php:','Today'=>'Hoje','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Consumo de tokens agrupado por funcionalidade, provedor e modelo. Registrado em cada chamada bem-sucedida de IA; os testes de conexão são deliberadamente excluídos para não distorcer os totais. A tabela subjacente agrega diariamente — escolha uma janela abaixo para visualizá-la.','Tone'=>'Tom','tone'=>'tom','Tone:'=>'Tom:','Too many AI requests. Please retry in %d seconds.'=>'Muitas solicitações de IA. Por favor, tente novamente em %d segundos.','Total'=>'Total','Total tokens'=>'Tokens totais','Translate'=>'Traduzir','Translate / Revise'=>'Traduzir / Revisar','Translate / Revise block'=>'Revisar / Traduzir bloco','Translate all'=>'Traduzir tudo','Translate chunk'=>'Traduzir trecho','Translate Content'=>'Traduzir conteúdo','Translate missing'=>'Falta tradução','Translate page…'=>'Traduzir página…','Translated content'=>'Conteúdo traduzido','Translated Names'=>'Nomes traduzidos','Translated title'=>'Título traduzido','Translated to:'=>'Traduzido para:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traduzido. Revise no Editor do Site — links internos, URLs de navegação e slugs de modelos não são atualizados automaticamente.','Translating…'=>'Traduzindo…','Translation'=>'Tradução','Translation Caching'=>'Cache de Tradução','Translation found but permalink could not be generated'=>'Tradução encontrada, mas o permalink não pôde ser gerado','Translation Limits'=>'Limites de Tradução','Translation Limits & Behavior'=>'Limites de Tradução e Comportamento','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Limites de Tradução: controla quais os papéis de utilizador que podem ativar a tradução AI, e define um orçamento mensal de tokens. Ultrapassar o orçamento suspende as chamadas de IA até ao reinício do mês.','Translation Memory'=>'Memória de tradução','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'A Memória de Tradução armazena resultados de IA por hash de conteúdo, par de línguas, fornecedor e modelo. Editar uma publicação invalida a entrada de cache para que a próxima chamada de tradução obtenha um resultado atualizado.','Translation Memory cleared. %d cached block was removed.'=>'Memória de tradução limpa. %d bloco em cache foi removido.' . "\0" . 'Memória de tradução limpa. %d blocos em cache foram removidos.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Memória de Tradução: armazena a publicação traduzida completa por hash de conteúdo. Limpe-a quando desejar forçar uma retradução de todas as publicações, independentemente de o conteúdo ter mudado ou não.','Translation workflow'=>'Fluxo de trabalho de tradução','Translation, Content Generator'=>'Tradução, Gerador de Conteúdo','Type'=>'Tipo','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Desinstalar Comportamento','Uninstall setting saved.'=>'Configuração de desinstalação guardada.','unknown error'=>'erro desconhecido','Unknown provider.'=>'Provedor desconhecido.','Up'=>'Para cima','Upload .mo file'=>'Carregar arquivo .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carregue arquivos .mo compilados para substituir as strings do plugin de terceiros para locais específicos — por exemplo, uma tradução personalizada do VikBooking que usa "apartamento" em vez de "quarto". Os arquivos devem seguir a convenção de nomenclatura do WordPress: {textdomain}-{locale}.mo (exemplo: vikbooking-ca.mo). Eles são armazenados na pasta de uploads e sobrevivem às atualizações do plugin.','Upload Override'=>'Carregar Substituição','URL could not be mapped to a post — check the link target exists'=>'URL não pôde ser mapeada para um post — verifique se o destino do link existe','URL structure'=>'Estrutura de URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Estrutura de URL: modo de prefixo de caminho (exemplo.com/de/) não requer alterações no servidor. modo de subdomínio (de.exemplo.com) requer um registo DNS curinga, um certificado SSL curinga, e uma alteração na configuração do servidor web — consulte o guia de Configuração do Servidor.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Utilize as abas na parte superior desta página para configurar cada área. Alterações na aba do Roteador entram em vigor imediatamente; alterações nas chaves de IA e configurações de modelo aplicam-se na próxima solicitação de IA.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabela de terminologia gerida pelo utilizador por par de línguas. As entradas são adicionadas ao prompt do sistema de tradução para que a IA utilize termos preferidos de forma consistente — fundamental para o vocabulário do domínio ("kWp", "PPA", "ponto de interligação"), nomes de marcas que não devem ser traduzidos e formulações regulatórias padronizadas. Ambos os campos de idioma são opcionais: deixe o "Idioma de origem" em branco para aplicar a entrada independentemente do idioma de origem; deixe o "Idioma de destino" em branco para aplicá-la a todos os idiomas de destino de uma só vez.','Using custom meta description.'=>'Usando meta descrição personalizada.','View'=>'Visualizar','View built-in default'=>'Ver padrão embutido','View details'=>'Ver detalhes','View Lingua Forge details'=>'Ver detalhes do Lingua Forge','Visit plugin site'=>'Visitar site do plugin','Warning:'=>'Aviso:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quando o registo de depuração está ativado (através do botão abaixo ou definindo LINGUAFORGE_AI_DEBUG no wp-config.php), os recursos de tradução de modelos e de tradução de modelos FSE escrevem os seus prompts de IA e respostas para o disco para resolução de problemas. Use esta seção para monitorar essa saída e limpá-la assim que tiver o que precisa — os ficheiros podem crescer rapidamente em páginas grandes. Configure o diretório de destino através do filtro linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quando ativado, os visitantes de primeira viagem sem cookie de idioma e sem prefixo de idioma na URL são redirecionados para a versão de idioma mais próxima. O redirecionamento é ignorado se o idioma preferido do navegador não estiver entre os idiomas ativos do roteador. Uma vez que um visitante seleciona um idioma através do alternador, o cookie tem prioridade e o cabeçalho do navegador é ignorado em visitas futuras.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Qual nível de modelo usar para tradução de página inteira. A qualidade usa o modelo configurado na tabela Modelos acima e é recomendado para traduções precisas e de formato longo. Mude para Leve apenas se velocidade ou custo forem prioridade e o conteúdo for curto.','WP-CLI reference'=>'Referência WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Escrever prompts e respostas de IA no disco para resolução de problemas','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Você também pode definir chaves como constantes ou variáveis de ambiente (por exemplo, no wp-config.php). Essas fontes são usadas automaticamente como fallback quando nenhuma chave do banco de dados está armazenada.','You do not have permission to manage these settings.'=>'Não tem permissão para gerir estas configurações.','You do not have permission to read this post.'=>'Você não tem permissão para ler esta publicação.','{n} stale path(s)'=>'{n} caminho(s) obsoleto(s)','— Any source language —'=>'— Qualquer idioma de origem —','— Any target language —'=>'— Qualquer idioma de destino —','— Any target —'=>'— Qualquer destino —','— Any —'=>'— Qualquer —','— auto-detect —'=>'— detectar automaticamente —','— select a language —'=>'— selecione um idioma —','— toggle in Settings → Behavior.'=>'— botão em Configurações → Comportamento.','← Back'=>'← Voltar','↑ Detected from current post'=>'↑ Detectado a partir da publicação atual','↺ Re-translate'=>'↺ Re-traduzir','↺ Refine'=>'↺ Refinar','↺ Refresh'=>'↺ Atualizar','↺ Refreshing…'=>'↺ Atualizando…','⚠ Borderline'=>'⚠ Limite','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Nenhum post <strong>{lang}</strong> encontrado. Certifique-se de que todos os posts traduzidos tenham a meta de idioma definida como <strong>{lang}</strong> na caixa de metadados de idioma.','⚠ No changes'=>'⚠ Sem alterações','⚠ No changes — re-scan?'=>'⚠ Sem alterações — re-escaneamento?','✅ Fixed ({n})'=>'✅ Corrigido ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Nenhum link quebrado ou incompatibilidade de modelo encontrada para <strong>{lang}</strong>. Escaneados <strong>{scanned}</strong> post(s) e página(s) — todas as verificações passaram. Os links das partes do modelo (cabeçalho, rodapé, barra lateral) não estão incluídos aqui — use o botão Corrigir Partes do Modelo para verificar esses separadamente.','✅ Template fixed'=>'✅ Modelo corrigido','✓ All parts created.'=>'✓ Todas as partes criadas.','✓ All templates created.'=>'✓ Todos os modelos criados.','✓ All translated.'=>'✓ Todas as traduções concluídas.','✓ Configured'=>'✓ Configurado','✓ Connection OK'=>'✓ Conexão OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Conteúdo gerado — veja a sobreposição para revisar, refinar e aplicar.','✓ Done'=>'✓ Concluído','✓ Enabled'=>'✓ Ativado','✓ Good length'=>'✓ Bom comprimento','✓ In safe storage'=>'✓ Em armazenamento seguro','✓ Language installed.'=>'✓ Língua instalada.','✓ Links fixed.'=>'✓ Links corrigidos.','✓ Nav refs fixed.'=>'✓ Referências de navegação corrigidas.','✓ Parts fixed.'=>'✓ Partes corrigidas.','✓ Pattern translated.'=>'✓ Padrão traduzido.','✓ Refined — review the updated draft above.'=>'✓ Refinado — reveja o rascunho atualizado acima.','✓ Translation saved'=>'✓ Tradução salva','✗ Disabled'=>'✗ Desativado','✗ Error:'=>'✗ Erro:','✗ Failed:'=>'✗ Falhou:','✗ Not configured'=>'✗ Não configurado','✗ Too long'=>'✗ Muito longo','✗ Too short'=>'✗ Muito curto','❌ Failed'=>'❌ Falhou','📄 Wrong template'=>'📄 Modelo incorreto','📍 Stale path (page moved)'=>'📍 Caminho obsoleto (página movida)']];
